    if (pretty) value.spaces2 else value.noSpaces

  def tokenize(value: JsonValue): Token =
    Token(render(value), TokenType.STRUCTURED, Map("json" -> true))

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    def descend(current: Json, parts: List[String]): Option[Json] = parts match {
      case Nil => Some(current)
      case head :: tail =>
        current.asObject.flatMap(_.apply(head)) match {
          case Some(next) => descend(next, tail)
          case None =>
            current.asArray.flatMap { array =>
              if (head.nonEmpty && head.forall(_.isDigit)) {
