final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = """.,!?;:'"()[]{}""".toSet

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripEdges(word, punctuation) else word
    val cased = if (lowercase) stripped.toLowerCase else stripped

    if (cased.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(limit) if cased.length > limit => cased.take(limit)
        case _ => cased
      }

      Option.when(truncated.nonEmpty)(truncated)
    }
  }

  private def stripEdges(value: String, chars: Set[Char]): String = {
    val leftTrimmed = value.dropWhile(chars.contains)
    leftTrimmed.reverse.dropWhile(chars.contains).reverse
  }

  private def words(text: String): Vector[String] =
    if (text.trim.isEmpty) Vector.empty
    else text.split("\\s+").toVector.filter(_.nonEmpty)

  def tokenize(text: String): List[Token] = {
    val result = ListBuffer.empty[Token]
    var currentPos = 0

    words(text).zipWithIndex.foreach { case (word, index) =>
      val start = text.indexOf(word, currentPos) match {
        case -1 => currentPos
        case found => found
      }
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> index, "original" -> word)
        )
      }

      currentPos = end
    }

    result.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words(text).foreach { word =>
      val start = text.indexOf(word, currentPos) match {
        case -1 => currentPos
        case found => found
      }
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

